// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.agent.ladbimport com.roshan.persona.agent.automation.AutomationMethodimport com.roshan.persona.agent.automation.AutomationOperationimport com.roshan.persona.agent.automation.AutomationProviderimport com.roshan.persona.agent.automation.AutomationResultimport com.roshan.persona.agent.automation.AutomationResultDataimport com.roshan.persona.agent.automation.ScrollDirectionimport timber.log.Timberimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — LADB Automation Provider (Module 9 v2 — audit P1). * * Translates [AutomationOperation]s into ADB shell commands executed via * [LadbConnection]. * * ## Operation → ADB shell mapping * * | Operation | ADB shell command | * |-----------|-------------------| * | Tap(x, y) | `input tap $x $y` | * | Swipe(...) | `input swipe $x1 $y1 $x2 $y2 $durationMs` | * | TypeText(text) | `input text "$text"` | * | ClickButtonByText(text) | `uiautomator dump` → parse XML → tap coords | * | ClickButtonByViewId(id) | `uiautomator dump` → parse XML → tap coords | * | Scroll(direction) | `input swipe 500 200 500 800 300` | * | PressKey(keyCode) | `input keyevent $keyCode` | * | OpenApp(packageName) | `monkey -p $packageName -c android.intent.category.LAUNCHER 1` | * * Falls back to [com.roshan.persona.agent.automation.AccessibilityAutomationProvider] * if the LADB connection drops. * * @see AutomationProvider * @see LadbConnection */@Singletonclass LadbAutomationProvider @Inject constructor(    private val connection: LadbConnection,) : AutomationProvider {    override val providerName: String = "LADB"    override val method: AutomationMethod = AutomationMethod.LADB    override fun isAvailable(): Boolean = connection.isReady    override suspend fun execute(operation: AutomationOperation): AutomationResult {        if (!connection.isReady) {            return AutomationResult.Failure(                operation = operation,                reason = "LADB not connected — fall back to Accessibility",                durationMs = 0L,            )        }        val startNanos = System.nanoTime()        val shellCommand = translateToShell(operation) ?: return AutomationResult.NotSupported(            operation = operation,            providerName = providerName,        )        val output = connection.executeShellCommand(shellCommand)        val durationMs = (System.nanoTime() - startNanos) / 1_000_000L        return if (output != null) {            AutomationResult.Success(                operation = operation,                durationMs = durationMs,                data = AutomationResultData.BooleanResult(true),            )        } else {            AutomationResult.Failure(                operation = operation,                reason = "Shell command failed: $shellCommand",                durationMs = durationMs,            )        }    }    /**     * Translate an [AutomationOperation] to an ADB shell command.     *     * Returns null for operations that require UI tree parsing (ClickButtonByText,     * ClickButtonByViewId) — those are better handled by AccessibilityAutomationProvider     * which has direct access to the accessibility tree.     */    private fun translateToShell(operation: AutomationOperation): String? = when (operation) {        is AutomationOperation.Tap -> "input tap ${operation.x.toInt()} ${operation.y.toInt()}"        is AutomationOperation.Swipe -> "input swipe ${operation.startX.toInt()} ${operation.startY.toInt()} ${operation.endX.toInt()} ${operation.endY.toInt()} ${operation.durationMs}"        is AutomationOperation.LongPress -> "input swipe ${operation.x.toInt()} ${operation.y.toInt()} ${operation.x.toInt()} ${operation.y.toInt()} ${operation.durationMs}"        is AutomationOperation.TypeText -> "input text \"${escapeShellArg(operation.text)}\""        is AutomationOperation.Scroll -> when (operation.direction) {            ScrollDirection.UP -> "input swipe 500 800 500 200 300"            ScrollDirection.DOWN -> "input swipe 500 200 500 800 300"            ScrollDirection.LEFT -> "input swipe 800 500 200 500 300"            ScrollDirection.RIGHT -> "input swipe 200 500 800 500 300"        }        is AutomationOperation.PressKey -> "input keyevent ${operation.keyCode}"        is AutomationOperation.OpenApp -> "monkey -p ${operation.packageName} -c android.intent.category.LAUNCHER 1"        is AutomationOperation.GetUiTree -> "uiautomator dump /dev/tty 2>/dev/null"        is AutomationOperation.TakeScreenshot -> "screencap -p"        // ClickButtonByText + ClickButtonByViewId require UI tree parsing —        // AccessibilityAutomationProvider handles these better.        is AutomationOperation.ClickButtonByText -> null        is AutomationOperation.ClickButtonByViewId -> null    }    /** Escape a string for safe inclusion in an ADB shell command. */    private fun escapeShellArg(text: String): String {        return text.replace("\\", "\\\\")            .replace("\"", "\\\"")            .replace("$", "\\$")            .replace("`", "\\`")    }    private companion object {        private const val TAG = "LadbAutomation"    }}